if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.priest.dps.Name"] = "Урон"
L["rm.era.priest.dps.Description"] = "Урон с 1 по 60 уровень; также ротация жреца по умолчанию всякий раз, когда не подходит встроенная ротация лекаря (в одиночной игре, для «Тьмы» или пока нет талантов). Облик Тьмы, как только изучен; перед боем щит в одиночной игре, затем Священный огонь (без Облика Тьмы), Взрыв разума или Кара. Слово Тьмы: Боль по одному разу на каждую цель, которая проживёт достаточно долго, Взрыв разума по готовности, Пытка разума как заполнитель (до неё — Кара и Кольцо Света) и жезл по умирающей цели или когда в одиночной игре кончается мана. Объятия вампира и Всепожирающая чума в долгих боях, но никогда в рейдах. Напоминания: Внутренний огонь, Стойкость, расовые положительные эффекты, Внутреннее сосредоточение вместе со Взрывом разума, Ментальный крик, когда до вас добираются два врага, а у вас половина здоровья, Уход в тень, когда ваша цель переключается на вас, Молитва отчаяния. Выбор цели, DoT на нескольких целях и понижение ранга заклинаний остаются за вами."
L["rm.era.priest.dps.simulator.Name"] = "Урон (рейд за нежить, симулятор)"
L["rm.era.priest.dps.simulator.Description"] = "Рекомендуемый приоритет урона с рейдовым выбором симулятор для жрецов-нежити: Внутреннее сосредоточение тратится на Всепожирающую чуму вместо Взрыва разума, а Всепожирающая чума применяется и в рейдах, поэтому используйте эту ротацию только там, где у вашего рейда есть свободные места для отрицательных эффектов. Без Объятий вампира. Альтернатива рекомендуемой встроенной ротации урона, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.era.priest.dps.warcrafttavern.Name"] = "Урон (Warcraft Tavern, экономия с жезлом)"
L["rm.era.priest.dps.warcrafttavern.Description"] = "Стиль прокачки Warcraft Tavern с минимальным простоем — альтернатива рекомендуемой встроенной ротации урона, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. В одиночной игре: Взрыв разума для начала боя, один раз Слово Тьмы: Боль, повторный Взрыв разума — только пока у цели больше 30% здоровья, и жезл между Взрывами разума вместо Кары или Пытки разума. Без автоматического щита перед боем. В группе: Слово Тьмы: Боль, Взрыв разума, Пытка разума. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.era.priest.healer.Name"] = "Лекарь"
L["rm.era.priest.healer.Description"] = "Выбирается в группе, когда «Свет» или «Послушание» — ваша основная ветка талантов. Лечит выбранную вами дружественную цель: Слово силы: Щит ниже 30%, Быстрое исцеление ниже 40%, рассеивание, Молитва исцеления, когда ранены трое из вашей группы, Большее исцеление (до его изучения — Исцеление или Малое исцеление) при здоровье ниже половины, Обновление в движении или при лёгком уроне, затем Исцеление 3-го ранга как экономное восполнение. Вне боя предлагает Стойкость на вашу цель. С враждебной целью — Слово Тьмы: Боль и Кара. Напоминания: Внутренний огонь, Стойкость, Божественный дух, Внутреннее сосредоточение, Молитва отчаяния; Придание сил по умолчанию выключено. Кого лечить и понижение ранга заклинаний остаются за вами."
L["rm.forever.priest.dps.Name"] = "Тьма и урон в одиночной игре"
L["rm.forever.priest.dps.Description"] = "«Тьма» и одиночная игра любого жреца с 1 по 60 уровень; также ротация жреца по умолчанию в Forever. Начинает бой со Слова силы: Щит (в одиночной игре) и Взрыва разума (Священный огонь для «Света» и «Послушания», Кара до Взрыва разума). Затем Облик Тьмы, как только изучен, ваши собственные Слово Тьмы: Боль и Всепожирающая чума, Взрыв разума, Священный огонь перед Исповедью для «Послушания», Пытка разума в Облике Тьмы; в одиночной игре до Облика Тьмы — Кольцо Света против трёх врагов с Праведным рвением, затем жезл (без него — Кара). В движении: Боль, Чума. Напоминания: Внутренний огонь, Стойкость, Божественный дух, расовые положительные эффекты, Объятия вампира, Внутреннее сосредоточение, Безмолвие, Свет Элуны; Ментальный крик по умолчанию выключен. В Forever здоровье и мана скрыты от аддонов, поэтому добивание Словом Тьмы: Смерть, лечение себя и Тёмная жертва остаются за вами. Составлено по руководствам бета-версии для 30 уровня; игра в Облике Тьмы следует Mobalytics."
L["rm.forever.priest.dps.mobalytics.Name"] = "Прокачка с DoT и жезлом (Mobalytics)"
L["rm.forever.priest.dps.mobalytics.Description"] = "Стиль прокачки Mobalytics — альтернатива рекомендуемой встроенной ротации «Тьма», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Взрыв разума и Священный огонь — только против сильных противников (элитных или на два уровня выше вас), ваши собственные Слово Тьмы: Боль и Всепожирающая чума, затем жезл (без него — Кара). В Облике Тьмы: Взрыв разума, Боль, Чума, Пытка разума. Щит и Обновление на себя между боями, Излечение болезни на себя. В Forever здоровье и мана скрыты от аддонов, поэтому лечение себя остаётся за вами. Распространение Боли на нескольких противников — на ваше усмотрение."
L["rm.forever.priest.healer.Name"] = "Лечение, Послушание и Свет"
L["rm.forever.priest.healer.Description"] = "Групповое лечение, когда «Послушание» или «Свет» — ваша основная ветка талантов, а Облик Тьмы вы не знаете. Лечит вашу текущую дружественную цель: перед боем Слово силы: Щит, Молитва восстановления и Обновление; Рассеивание заклинаний и Устранение болезни или Излечение болезни; Молитва восстановления; Кольцо Света при Праведном рвении; Исповедь; Обновление, если его нет; Исцеление (до него — Малое исцеление). Против врага: Слово Тьмы: Боль, Священный огонь, Исповедь, Кара, жезл. Напоминания: Внутренний огонь, Стойкость, Божественный дух, Придание сил на другого игрока, Внутреннее сосредоточение в бою и расовые заклинания. В Forever здоровье и мана скрыты от аддонов, поэтому единственный признак того, кого нужно лечить, — выбранная вами цель; экстренные исцеления, Молитва исцеления, Связующее исцеление, Великое и Быстрое исцеление, Молитва отчаяния и Тёмная жертва остаются за вами. Кого лечить и ранг выбираете вы; лекарь «Послушания» до Исповеди (20–29 уровни) выбирает эту ротацию вручную."
L["rm.mop.priest.discipline.Name"] = "Рекомендуемая"
L["rm.mop.priest.discipline.Description"] = "Лечение «Послушания» с 10 по 90 уровень; выбирается при специализации «Послушание». Выберите союзника, чтобы лечить его: Слово силы: Щит, когда у него мало здоровья, перед боем и примерно каждые 12 секунд ради Вознесения; Быстрое исцеление при Пробуждении Света; Исповедь; Быстрое исцеление, когда здоровья очень мало; Связующее исцеление, когда ранены вы оба; Молитва восстановления; Молитва исцеления и ваш талант 6-го ряда, когда ранены трое союзников; Сильное исцеление; Обновление в движении; Исцеление для восполнения. Под Щитом души предлагает Молитву исцеления или Сильное исцеление. Выберите врага, чтобы лечить через Искупление вины: Исповедь, Слово силы: Утешение или Священный огонь, ваш талант 6-го ряда против групп, Слово Тьмы: Боль в одиночной игре, Кара. Напоминания: Внутренний огонь, Стойкость, Архангел при пяти наложениях Приверженности, Внутреннее сосредоточение, Подавление боли на умирающую цель, Исчадие Тьмы или Подчиняющий разум ради маны, Придание сил, Молитва отчаяния. За вами остаются: кого лечить, момент для Щита души (напоминание можно включить), Слово силы: Барьер, Вхождение в Бездну и наложения Милости на танке."
L["rm.mop.priest.holy.Name"] = "Рекомендуемая"
L["rm.mop.priest.holy.Description"] = "Лечение «Света» с 10 по 90 уровень; выбирается при специализации «Свет». Выберите союзника, чтобы лечить его: Слово Света: Безмятежность в Чакре: безмятежность; Слово силы: Щит — только когда он вот-вот умрёт; Быстрое исцеление при Пробуждении Света; Молитва восстановления; Быстрое исцеление, когда здоровья очень мало; Связующее исцеление, когда ранены вы оба; в группе, когда ранены трое союзников, — Круг исцеления, Слово Света: Святилище в Чакре: святилище, ваш талант 6-го ряда и Молитва исцеления; Обновление; Сильное исцеление при малом здоровье или при двух наложениях Прозорливости; Исцеление. Выберите врага, чтобы наносить урон: Слово Света: Воздаяние, Слово силы: Утешение или Священный огонь, Слово Тьмы: Боль в одиночной игре, ваш талант 6-го ряда против групп, Кара. Пустая чакра заполняется за вас (святилище в рейде, безмятежность в группе, воздаяние в одиночной игре) и никогда не меняется. Напоминания: Внутренний огонь, Стойкость, Оберегающий дух на умирающую цель, Божественный гимн, когда пять союзников тяжело ранены, Исчадие Тьмы или Подчиняющий разум ради маны, Придание сил, Молитва отчаяния. За вами остаются: кого лечить, размещение Слова Света: Святилище, Колодец Света и Вхождение в Бездну."
L["rm.mop.priest.holy.icyveins.Name"] = "Экстренное лечение последним (Icy Veins)"
L["rm.mop.priest.holy.icyveins.Description"] = "По умолчанию выключена. Порядок «Света» по Icy Veins, выбираемый по вашей чакре. В Чакре: святилище — Слово Света: Святилище, когда ранены трое союзников, Обновление, Круг исцеления, Молитва восстановления, Молитва исцеления, затем Связующее исцеление и Быстрое исцеление — только в экстренных случаях. Иначе: Обновление, Слово Света: Безмятежность, Молитва восстановления, Сильное исцеление, Исцеление, Связующее исцеление, Быстрое исцеление, в последнюю очередь Слово силы: Щит и Быстрое исцеление как заполнитель, пока вы не изучили Исцеление. Те же переключение, напоминания и список урона, что и в рекомендуемой встроенной ротации «Свет»; чтобы использовать её, включите её и выключите ту."
L["rm.mop.priest.shadow.Name"] = "Рекомендуемая"
L["rm.mop.priest.shadow.Description"] = "Урон «Тьмы» с 10 по 90 уровень; выбирается при специализации «Тьма». Начинает бой Пронзанием разума, Взрывом разума или вашими DoT. Всепожирающая чума при трёх Сферах Тьмы (когда Взрыв разума готов или до него ещё шесть секунд), Взрыв разума, Слово Тьмы: Смерть при здоровье ниже 20%, Пытка разума, пока висит ваша Всепожирающая чума, если вы взяли «Утешение и безумие», Слово Тьмы: Боль и Прикосновение вампира обновляются ближе к концу на цели, которая проживёт достаточно долго, Пронзание разума при Наступлении Тьмы, Сияние, Каскад или Божественная звезда на лучшей для них дистанции, затем Пытка разума. Пытка разума прерывается ради Взрыва разума или Слова Тьмы: Смерть либо после второго такта; другие поддерживаемые заклинания не прерываются никогда. В движении предлагает только мгновенные заклинания. Против пяти и более врагов: ваш талант 6-го ряда, DoT на вашей цели и Иссушение разума. Напоминания: Облик Тьмы, Внутренний огонь, Стойкость, Безмолвие против прерываемых заклинаний, Исчадие Тьмы или Подчиняющий разум и Придание сил в долгих боях, Объятия вампира, Молитва отчаяния и Слияние с Тьмой при низком здоровье. За вами остаются: DoT на других целях и место для Иссушения разума."
L["rm.mop.priest.shadow.warcrafttavern.Name"] = "Без приоритета Безумия (Warcraft Tavern)"
L["rm.mop.priest.shadow.warcrafttavern.Description"] = "По умолчанию выключена. Порядок «Тьмы» по Warcraft Tavern: Всепожирающая чума при трёх Сферах Тьмы, Слово Тьмы: Смерть ниже 20%, Взрыв разума, Прикосновение вампира, Слово Тьмы: Боль, Пронзание разума при Наступлении Тьмы, ваш талант 6-го ряда, Пытка разума. В отличие от рекомендуемой встроенной ротации «Тьма», никогда не поднимает Пытку разума под Всепожирающей чумой и не придерживает Всепожирающую чуму ради Взрыва разума. Те же шаги начала боя, движения, групп и напоминаний; чтобы использовать её, включите её и выключите рекомендуемую."
L["rm.mop.priest.unspecialized.Name"] = "Без специализации"
L["rm.mop.priest.unspecialized.Description"] = "Для уровней 1–9 или любого жреца, который ещё не выбрал специализацию. С врагом: Слово Тьмы: Боль, если он проживёт достаточно долго, затем Кара. С союзником: Быстрое исцеление, когда у него мало здоровья, иначе Слово силы: Щит. Напоминания: Внутренний огонь и щит на себя, когда вы в одиночку и ранены. Выбор специализации на 10 уровне переключает на её собственную встроенную ротацию."
L["rm.retail.priest.discipline.Name"] = "Искупление вины (Icy Veins)"
L["rm.retail.priest.discipline.Description"] = "«Послушание» в Midnight, для справки: Боевой помощник Blizzard не охватывает лекарей, игра скрывает здоровье всех в бою, а Rotation Master выбирает заклинание, а не цель, поэтому эта ротация наносит урон, который лечит через Искупление вины, а решать, кого лечить, оставляет вам. С дружественной целью: Слово силы: Щит (Щит Бездны), Исповедь, Быстрое исцеление. С враждебной целью: Слово Тьмы: Боль, если вы не применяли его 12 секунд, Взрыв разума, Исповедь, Слово силы: Щит, Слово Тьмы: Смерть, Вспышка Бездны, Кара. Напоминания в бою: Слово силы: Сияние, Проповедь, Искреннее раскаяние, Подавление боли на дружественную цель; Слово силы: Стойкость между боями. Молитва отчаяния — на ваше усмотрение. Когда разгонять рейд перед сильным уроном, решаете вы."
L["rm.retail.priest.discipline.wowhead.Name"] = "Сначала Слово Тьмы: Смерть, для справки (Wowhead)"
L["rm.retail.priest.discipline.wowhead.Description"] = "Только для справки, по умолчанию выключена: порядок Оракула по Wowhead для 1-го сезона, который поддерживает Слово Тьмы: Боль, читая отрицательный эффект, скрытый Midnight в бою. Слово Тьмы: Боль, Слово Тьмы: Смерть по готовности, Исповедь, Взрыв разума, Кара; с дружественной целью первой идёт Исповедь. Те же напоминания, что и во встроенной ротации Icy Veins."
L["rm.retail.priest.holy.Name"] = "Icy Veins"
L["rm.retail.priest.holy.Description"] = "«Свет» в Midnight, для справки: игра скрывает здоровье всех в бою, а Rotation Master выбирает заклинание, а не цель, поэтому эта ротация поддерживает в обороте ваши Слова Света, Молитву восстановления и срабатывания на любой выбранной вами цели, а сортировку раненых оставляет вам. С дружественной целью: Слово Света: Освящение, Слово Света: Безмятежность, Молитва восстановления, Молитва исцеления при Пробуждении Света, Благодарение, Молитва исцеления с Ткачом Света, Быстрое исцеление при Пробуждении Света, Молитва исцеления в группе, Кольцо Света в движении, Быстрое исцеление. С враждебной целью: Слово Света: Наказание, Священный огонь, Кольцо Света в движении, Кара. Напоминания: Прославление, Божественный гимн и Сияние в бою, Оберегающий дух на дружественную цель (здоровье на Retail скрыто, поэтому решать, не вот-вот ли она умрёт, вам), Слово силы: Стойкость. Молитва отчаяния — за вами."
L["rm.retail.priest.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.priest.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию жреца). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций жреца, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.priest.shadow.Name"] = "Боевой помощник Blizzard"
L["rm.retail.priest.shadow.Description"] = "Рекомендуется для специализации «Тьма» в Midnight. В бою игра теперь скрывает от аддонов ваши DoT, положительные эффекты, время восстановления и здоровье, поэтому эта ротация показывает собственное предложение Боевого помощника Blizzard (ротация одной кнопкой, которая поддерживает ваши DoT, Облик Тьмы и Облик Бездны и даёт Пытке разума завершиться) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Придание сил в течение 20 секунд после применения Облика Бездны, Облик Тьмы и Слово силы: Стойкость между боями, Безмолвие против прерываемого заклинания (оно загорается только там, где игра позволяет прочитать заклинание). Здоровье на Retail скрыто, поэтому Молитва отчаяния — на ваше усмотрение."
L["rm.retail.priest.shadow.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.priest.shadow.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft читает таймеры DoT, эффект «Безумие» и Облик Бездны, которые Midnight скрывает в бою; безумие и здоровье на Retail скрыты, поэтому «Безумие» при максимуме запаса безумия, добивание Словом Тьмы: Смерть и Молитва отчаяния остаются за вами. Прикосновение вампира перед боем; Мощный удар щупальцем, чтобы наложить Прикосновение вампира; Прикосновение вампира и Слово Тьмы: Боль обновляются в последние 30% длительности; Слово Тьмы: Безумие, когда его эффект заканчивается или во время Облика Бездны; Вспышка Бездны во время «Безумия»; Мощный удар щупальцем при двух зарядах; Поток Бездны; Взрыв разума; Мощный удар щупальцем; Пытка разума: безумие во время «Безумия»; Залп Бездны; Слово Тьмы: Смерть и Слово Тьмы: Боль в движении; Пытка разума, прерываемая ради готового Взрыва разума. Напоминания: Сияние, Облик Бездны при обоих DoT, Придание сил во время Облика Бездны."
L["rm.sod.priest.dps.Name"] = "Урон (SoD)"
L["rm.sod.priest.dps.Description"] = "Урон в игровых мирах сезона открытий с 1 по 60 уровень с выгравированными вами рунами. Облик Тьмы; Прикосновение вампира или Взрыв разума для начала боя (до Облика Тьмы — Исповедь, Священный огонь или Кара). Чума Бездны, Слово Тьмы: Боль и Прикосновение вампира постоянно поддерживаются (ближе к концу обновляются, только если не выгравированы Боль и страдание), Взрыв разума по готовности, Пытка разума при Расплавленном лике, Слово Тьмы: Смерть, пока у вас больше половины здоровья, затем Пронзание разума как заполнитель или Пытка разума с комплектом из шести предметов 8-й фазы. Портал Бездны и Иссушение разума против четырёх и более врагов. Жезл по умирающей цели в одиночной игре. Напоминания: Внутренний огонь, Стойкость, Гомункулы, Исчадие Тьмы, Око Бездны и Слияние с Тьмой, Внутреннее сосредоточение, Ментальный крик, Уход в тень, Молитва отчаяния."
L["rm.sod.priest.dps.wowhead.Name"] = "Урон (SoD, наложения Пронзания разума по Wowhead)"
L["rm.sod.priest.dps.wowhead.Description"] = "Подход Wowhead и Warcraft Tavern для сезона открытий — альтернатива рекомендуемой встроенной ротации урона для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Взрыв разума ждёт трёх ваших наложений Пронзания разума на цели (пока вы не выгравировали Пронзание разума, он применяется как обычно), Пытка разума — только при Расплавленном лике, Пронзание разума как заполнитель. Всё остальное совпадает с рекомендуемой встроенной ротацией."
L["rm.sod.priest.healer.Name"] = "Лекарь (SoD)"
L["rm.sod.priest.healer.Description"] = "Выбирается в игровых мирах сезона открытий в группе, когда «Свет» или «Послушание» — ваша основная ветка талантов; следует Icy Veins. Лечит выбранную вами дружественную цель: Молитва восстановления перед боем и всякий раз, когда готова, Щит при здоровье ниже половины, Исповедь, мгновенное Быстрое исцеление при Пробуждении Света, экстренное Быстрое исцеление, рассеивание, Круг исцеления и Молитва исцеления, когда ранены трое из вашей группы, Большее исцеление при здоровье ниже половины, Обновление в движении или при лёгком уроне, затем Исцеление. С враждебной целью — Боль, Чума Бездны, Исповедь, Священный огонь и Кара. Среди напоминаний: Исчадие Тьмы, Подавление боли на умирающую цель, Слово Силы: Барьер и Дух воздаяния, когда группа ранена."
L["rm.sod.priest.healer.warcrafttavern.Name"] = "Лекарь (SoD, Warcraft Tavern)"
L["rm.sod.priest.healer.warcrafttavern.Description"] = "Цикл Прозорливости по Warcraft Tavern, рассчитанный на Прозорливость и Оберег души, — альтернатива рекомендуемой встроенной ротации лекаря для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Молитва восстановления по готовности, Щит на вашу цель всякий раз, когда на неё можно его наложить (с выгравированным Оберегом души; иначе ниже половины здоровья), Исповедь при сильном уроне, Круг исцеления, когда ранены трое, Большее исцеление или Молитва исцеления при трёх наложениях Прозорливости, Обновление при незначительном уроне и Быстрое исцеление при лёгких ранениях, чтобы набирать наложения (с выгравированной Прозорливостью; иначе ниже 30%)."
L["rm.tbc.priest.dps.icyveins.Name"] = "Урон (Icy Veins)"
L["rm.tbc.priest.dps.icyveins.Description"] = "Урон с 1 по 70 уровень; используется всегда, когда не подходит встроенная ротация лекаря. Сначала Кара и жезл, затем Взрыв разума, Слово Тьмы: Боль, Пытка разума, Облик Тьмы, Прикосновение вампира и Слово Тьмы: Смерть по мере изучения; DoT — раньше Взрыва разума; в одиночной игре умирающую цель добивает жезл. Жрецы веток «Свет» и «Послушание», выполняющие задания, получают Священный огонь и Кару. Напоминания: Внутренний огонь, Стойкость, расовые положительные эффекты, Внутреннее сосредоточение, Исчадие Тьмы. Пытка разума, прошедшая первый такт, обрывается ради готового Взрыва разума или Слова Тьмы: Смерть при здоровье цели выше половины. Щиты и лечение остаются за вами."
L["rm.tbc.priest.dps.wowhead.Name"] = "Урон (Wowhead)"
L["rm.tbc.priest.dps.wowhead.Description"] = "Урон по руководствам Wowhead — альтернатива рекомендуемой встроенной ротации урона от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Взрыв разума начинает бой и идёт раньше обновления DoT, Объятия вампира — только когда падает ваше здоровье, а умирающую цель добивают заклинаниями, а не жезлом. В остальном — как рекомендуемая встроенная ротация."
L["rm.tbc.priest.healer.icyveins.Name"] = "Лекарь (Icy Veins)"
L["rm.tbc.priest.healer.icyveins.Description"] = "Лечение в порядке Icy Veins: щит, рассеивание, Связующее исцеление, Обновление, Быстрое исцеление, Сильное исцеление (любого ранга), групповое лечение и последней — Молитва восстановления. Кого лечить, выбираете вы. Альтернатива рекомендуемой встроенной ротации лекаря от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.tbc.priest.healer.wowhead.Name"] = "Лекарь (Wowhead)"
L["rm.tbc.priest.healer.wowhead.Description"] = "Лечение в группе, когда «Свет» или «Послушание» — ваша основная ветка талантов. Советы даются для дружественного юнита в цели; кого лечить, выбираете вы. Молитва восстановления перед боем и всякий раз по готовности, Обновление, Слово силы: Щит в экстренных случаях, рассеивание, Круг исцеления или Молитва исцеления при уроне по группе, Связующее, Быстрое и Сильное исцеление, а также Сильное исцеление 1-го ранга как дешёвая подпитка. Если в цели враг, предлагает немного урона."
